        ["movementId2"] = MovementId2,
        ["journalNumber"] = JournalNumber,
        ["outcome"] = Outcome,
    };

    /// <summary>CobolCodec marshalling of every field (contracts 4.4): PIC X(n) Windows-1252 + right truncation, numbers rounded to scale and cut to the PIC digits.</summary>
    public void Normalize()
    {
        ReceiptRef = CobolText.Trimmed(ReceiptRef, 30);
        OrderNumber = CobolText.Trimmed(OrderNumber, 30);
        Supplier = CobolText.Trimmed(Supplier, 20);
        ItemCode = CobolText.Trimmed(ItemCode, 40);
        LotCode = CobolText.Trimmed(LotCode, 30);
        SerialNo = CobolText.Trimmed(SerialNo, 40);
        Warehouse = CobolText.Trimmed(Warehouse, 20);
        Location = CobolText.Trimmed(Location, 20);
        GoodLocation = CobolText.Trimmed(GoodLocation, 20);
        UomCode = CobolText.Trimmed(UomCode, 10);
        InspectDate = (int)CaJson.Digits(InspectDate, 8, unsigned: true);
        Inspector = CobolText.Trimmed(Inspector, 20);
        QuarantineQty = CobolNumeric.Normalize(QuarantineQty, 19, 6, true);
        InspectedQty = CobolNumeric.Normalize(InspectedQty, 19, 6, true);
        AcceptedQty = CobolNumeric.Normalize(AcceptedQty, 19, 6, true);
        RejectedQty = CobolNumeric.Normalize(RejectedQty, 19, 6, true);
        ReworkQty = CobolNumeric.Normalize(ReworkQty, 19, 6, true);
        Disposition = CobolText.Trimmed(Disposition, 12);
        RejectReason = CobolText.Trimmed(RejectReason, 20);
        RejectNarr = CobolText.Trimmed(RejectNarr, 200);
        ConcessionRef = CobolText.Trimmed(ConcessionRef, 40);
        ConcessionBy = CobolText.Trimmed(ConcessionBy, 20);
        CertRequired = CobolText.Trimmed(CertRequired, 1);
        CertRef = CobolText.Trimmed(CertRef, 60);
        UnitCost = CobolNumeric.Normalize(UnitCost, 17, 6, true);
        ReworkCostGbp = CobolNumeric.Normalize(ReworkCostGbp, 15, 2, true);
        RemainingQty = CobolNumeric.Normalize(RemainingQty, 19, 6, true);
        ToGoodQty = CobolNumeric.Normalize(ToGoodQty, 19, 6, true);
        ToScrapQty = CobolNumeric.Normalize(ToScrapQty, 19, 6, true);
        HeldForRetQty = CobolNumeric.Normalize(HeldForRetQty, 19, 6, true);
        ScrapValueGbp = CobolNumeric.Normalize(ScrapValueGbp, 15, 2, true);
        QualityStatus = CobolText.Trimmed(QualityStatus, 12);
        MovementId = CaJson.Digits(MovementId, 17);
        MovementId2 = CaJson.Digits(MovementId2, 17);
        JournalNumber = CobolText.Trimmed(JournalNumber, 30);
        Outcome = CobolText.Trimmed(Outcome, 10);
    }

